<?php
namespace App\Modules\CashManagement\Application;
use App\Models\User;use App\Modules\Audit\Application\RecordAuditEvent;use App\Modules\CashManagement\Domain\Enums\CashSessionStatus;use App\Modules\CashManagement\Domain\Models\CashSession;use App\Modules\Identity\Application\UseAuthorization;use App\Modules\Identity\Domain\Models\AuthorizationRequest;use DomainException;use Illuminate\Support\Facades\DB;
class CloseCashSession {public function __construct(private readonly ExpectedCashSessionBalance $expected,private readonly UseAuthorization $useAuthorization,private readonly RecordAuditEvent $audit){}public function execute(CashSession $session,int $counted,string $reason,User $actor,?AuthorizationRequest $authorization=null):CashSession{return DB::transaction(function()use($session,$counted,$reason,$actor,$authorization){$session=CashSession::query()->lockForUpdate()->findOrFail($session->id);if($session->status!==CashSessionStatus::Open)throw new DomainException('La sesión de caja no está abierta.');if($counted<0)throw new DomainException('El saldo contado no puede ser negativo.');$expected=$this->expected->execute($session);$difference=$counted-$expected;if($difference!==0&&trim($reason)==='')throw new DomainException('La diferencia de caja requiere explicación.');$threshold=(int)config('business.cash_difference_authorization_threshold',10000);if(abs($difference)>$threshold){if(!$authorization?->isUsable()||$authorization->approval_permission!=='cash.authorize-difference'||$authorization->resource_type!==$session->getMorphClass()||(string)$authorization->resource_id!==(string)$session->id)throw new DomainException('La diferencia supera el límite y requiere autorización vigente.');$this->useAuthorization->execute($authorization);}$session->update(['expected_closing_amount'=>$expected,'counted_closing_amount'=>$counted,'difference_amount'=>$difference,'difference_reason'=>$reason,'closed_by'=>$actor->id,'closed_at'=>now(),'status'=>CashSessionStatus::Closed,'authorization_request_id'=>$authorization?->id]);$this->audit->execute('cash.session_closed',$session,$actor,after:$session->toArray(),authorizationRequestId:$authorization?->id);return $session;});}}
